{'code': "reg = QgsApplication.processingRegistry()
alg = reg.algorithmById('gdal:warpreproject')
if alg is None:
    result = {'found': False}
else:
    params = []
    for p in alg.parameterDefinitions():
        entry = {'name': p.name(), 'desc': p.description(), 'type': p.type(), 'default': str(p.defaultValue())}
        if hasattr(p, 'options'):
            entry['options'] = p.options()
        params.append(entry)
    result = {
        'found': True,
        'id': alg.id(),
        'name': alg.displayName(),
        'group': alg.group(),
        'params': params,
    }
"}
